package com.nexushr.controller;
import com.nexushr.dto.EmployeeDtos.Request; import com.nexushr.model.*; import com.nexushr.repo.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
import org.springframework.web.server.ResponseStatusException;

@RestController @RequestMapping("/api/employees") public class EmployeeController { final EmployeeRepository repo; final DepartmentRepository deps; final EmployeeRepository employees; public EmployeeController(EmployeeRepository r,DepartmentRepository d){repo=r;deps=d;employees=r;} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @GetMapping public List<Employee> all(){return repo.findAll();} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @GetMapping("/{id}") public Employee one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @PostMapping public Employee create(@RequestBody Request x){Employee e=new Employee(); map(e,x); return repo.save(e);} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @PutMapping("/{id}") public Employee update(@PathVariable Long id,@RequestBody Request x){Employee e=one(id);map(e,x);return repo.save(e);} @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')") @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} void map(Employee e,Request x){if(e.employeeCode==null||e.employeeCode.isBlank())e.employeeCode="EMP"+System.currentTimeMillis()%1000000;e.name=x.name();e.email=x.email();e.phone=x.phone();e.designation=x.designation();e.joiningDate=x.joiningDate();e.salary=x.salary()==null?0:x.salary(); if(x.employmentType()!=null)e.employmentType=EmploymentType.valueOf(x.employmentType()); if(x.departmentId()!=null)e.department=deps.findById(x.departmentId()).orElse(null); if(x.managerId()!=null){Employee manager=employees.findById(x.managerId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Manager not found")); if(manager.id.equals(e.id))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Employee cannot report to themselves"); e.manager=manager;} else e.manager=null;} }
